var enumAssistantTurnOrigin = [...]schema.EnumValue{
	{Value: `Person`, Label: `Person`},
	{Value: `DecisionFollowUp`, Label: `Decision Follow Up`, Doc: `AssistantTurnOriginDecisionFollowUp is the turn in which the agent says what came of a proposal somebody decided, wherever they decided it.`},
	{Value: `Scheduled`, Label: `Scheduled`, Doc: `AssistantTurnOriginScheduled is a run of a request the person scheduled in the conversation, asked on their behalf when its time came.`},
	{Value: `Compaction`, Label: `Compaction`, Doc: `AssistantTurnOriginCompaction is the conversation being summarized to free its context. It holds the conversation's one live slot like any reply, so nothing is asked while the history is being rewritten, and it is stopped the way a reply is.`},
	{Value: `WaitResolved`, Label: `Wait Resolved`, Doc: `AssistantTurnOriginWaitResolved is the turn in which the agent picks up work it parked on a wait, once what it waited for happened or the wait ran out.`},
}

